-- =====================================================================
-- PROYECTO SEMESTRAL 2026 - TDFI103 Bases de Datos - Fase 2
-- Caso 2: Sistema Integral de Gestión de Centros de Turismo Astronómico
-- Motor: MySQL 8.x
-- Parte 1: creación de la base de datos, tablas y restricciones
-- =====================================================================

DROP DATABASE IF EXISTS astronomia_turismo;
CREATE DATABASE astronomia_turismo
    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE astronomia_turismo;

SET FOREIGN_KEY_CHECKS = 0;

-- ---------------------------------------------------------------------
-- REGION
-- ---------------------------------------------------------------------
CREATE TABLE region (
    cod_region              INT           NOT NULL AUTO_INCREMENT,
    nombre_oficial          VARCHAR(80)   NOT NULL,
    superficie_protegida    DECIMAL(12,2) NOT NULL COMMENT 'km2',
    presupuesto_actividades DECIMAL(14,2) NOT NULL COMMENT 'CLP',
    CONSTRAINT pk_region PRIMARY KEY (cod_region),
    CONSTRAINT uq_region_nombre UNIQUE (nombre_oficial),
    CONSTRAINT ck_region_superficie CHECK (superficie_protegida >= 0),
    CONSTRAINT ck_region_presupuesto CHECK (presupuesto_actividades >= 0)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- CENTRO ASTRONOMICO  (coordenadas = atributo compuesto latitud/longitud;
-- fecha de inauguración = DATE en lugar de día/mes/año separados)
-- ---------------------------------------------------------------------
CREATE TABLE centro_astronomico (
    cod_centro              INT           NOT NULL AUTO_INCREMENT,
    nombre_centro           VARCHAR(100)  NOT NULL,
    fecha_inauguracion      DATE          NOT NULL,
    altitud                 INT           NOT NULL COMMENT 'metros sobre el nivel del mar',
    latitud                 DECIMAL(9,6)  NOT NULL,
    longitud                DECIMAL(9,6)  NOT NULL,
    capacidad_maxima_diaria INT           NOT NULL,
    presupuesto_anual       DECIMAL(14,2) NOT NULL COMMENT 'CLP',
    estado_operativo        VARCHAR(20)   NOT NULL DEFAULT 'Operativo',
    nivel_certificacion     VARCHAR(20)   NOT NULL,
    cod_region              INT           NOT NULL,
    CONSTRAINT pk_centro PRIMARY KEY (cod_centro),
    CONSTRAINT uq_centro_nombre UNIQUE (nombre_centro),
    CONSTRAINT fk_centro_region FOREIGN KEY (cod_region)
        REFERENCES region (cod_region),
    CONSTRAINT ck_centro_altitud CHECK (altitud BETWEEN 0 AND 6500),
    CONSTRAINT ck_centro_latitud CHECK (latitud BETWEEN -90 AND 90),
    CONSTRAINT ck_centro_longitud CHECK (longitud BETWEEN -180 AND 180),
    CONSTRAINT ck_centro_capacidad CHECK (capacidad_maxima_diaria > 0),
    CONSTRAINT ck_centro_presupuesto CHECK (presupuesto_anual >= 0),
    CONSTRAINT ck_centro_estado CHECK (estado_operativo IN ('Operativo','En mantencion','Inactivo')),
    CONSTRAINT ck_centro_certificacion CHECK (nivel_certificacion IN ('Bronce','Plata','Oro','Platino'))
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- ZONA DE OBSERVACION (entidad débil de CENTRO: PK compuesta)
-- ---------------------------------------------------------------------
CREATE TABLE zona_observacion (
    cod_centro           INT          NOT NULL,
    n_zona               SMALLINT     NOT NULL COMMENT 'número interno válido solo dentro del centro',
    nombre_zona          VARCHAR(80)  NOT NULL,
    superficie           DECIMAL(10,2) NOT NULL COMMENT 'm2',
    nivel_oscuridad      TINYINT      NOT NULL COMMENT 'escala 1 (muy luminosa) a 10 (muy oscura)',
    capacidad_maxima     INT          NOT NULL,
    equipamiento_disponible VARCHAR(200) NOT NULL,
    nivel_acceso         VARCHAR(25)  NOT NULL,
    CONSTRAINT pk_zona PRIMARY KEY (cod_centro, n_zona),
    CONSTRAINT fk_zona_centro FOREIGN KEY (cod_centro)
        REFERENCES centro_astronomico (cod_centro) ON DELETE CASCADE,
    CONSTRAINT ck_zona_n CHECK (n_zona > 0),
    CONSTRAINT ck_zona_superficie CHECK (superficie > 0),
    CONSTRAINT ck_zona_oscuridad CHECK (nivel_oscuridad BETWEEN 1 AND 10),
    CONSTRAINT ck_zona_capacidad CHECK (capacidad_maxima > 0),
    CONSTRAINT ck_zona_acceso CHECK (nivel_acceso IN ('Publico','Restringido','Solo investigadores'))
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- FENOMENO ASTRONOMICO + especialización parcial y disjunta.
-- tipo_clasificacion (NULL = sin clasificar) + clave compuesta
-- (cod_fenomeno, tipo_clasificacion) garantiza que un fenómeno solo pueda
-- existir en UN subtipo (disyunción).
-- ---------------------------------------------------------------------
CREATE TABLE fenomeno_astronomico (
    cod_fenomeno              INT          NOT NULL AUTO_INCREMENT,
    nombre_fenomeno           VARCHAR(120) NOT NULL,
    descripcion               TEXT         NULL,
    fecha_primera_observacion DATE         NOT NULL,
    frecuencia_estimada       DECIMAL(8,2) NOT NULL COMMENT 'ocurrencias estimadas por año',
    nivel_interes_cientifico  TINYINT      NOT NULL COMMENT '1 (bajo) a 5 (muy alto)',
    tipo_clasificacion        VARCHAR(20)  NULL COMMENT 'NULL = sin clasificar',
    activo                    TINYINT(1)   NOT NULL DEFAULT 1 COMMENT 'desactivación lógica',
    CONSTRAINT pk_fenomeno PRIMARY KEY (cod_fenomeno),
    CONSTRAINT uq_fenomeno_nombre UNIQUE (nombre_fenomeno),
    CONSTRAINT uq_fenomeno_tipo UNIQUE (cod_fenomeno, tipo_clasificacion),
    CONSTRAINT ck_fenomeno_frecuencia CHECK (frecuencia_estimada >= 0),
    CONSTRAINT ck_fenomeno_interes CHECK (nivel_interes_cientifico BETWEEN 1 AND 5),
    CONSTRAINT ck_fenomeno_tipo CHECK (tipo_clasificacion IS NULL
        OR tipo_clasificacion IN ('SOLAR','LUNAR','ESPACIO_PROFUNDO'))
) ENGINE=InnoDB;

CREATE TABLE fenomeno_solar (
    cod_fenomeno       INT         NOT NULL,
    tipo_clasificacion VARCHAR(20) NOT NULL DEFAULT 'SOLAR',
    magnitud_erupcion  DECIMAL(4,1) NOT NULL COMMENT 'escala logarítmica de intensidad de la erupción',
    CONSTRAINT pk_fenomeno_solar PRIMARY KEY (cod_fenomeno),
    CONSTRAINT ck_solar_tipo CHECK (tipo_clasificacion = 'SOLAR'),
    CONSTRAINT ck_solar_magnitud CHECK (magnitud_erupcion >= 0),
    CONSTRAINT fk_solar_fenomeno FOREIGN KEY (cod_fenomeno, tipo_clasificacion)
        REFERENCES fenomeno_astronomico (cod_fenomeno, tipo_clasificacion)
) ENGINE=InnoDB;

CREATE TABLE fenomeno_lunar (
    cod_fenomeno       INT         NOT NULL,
    tipo_clasificacion VARCHAR(20) NOT NULL DEFAULT 'LUNAR',
    fase               VARCHAR(20) NOT NULL,
    CONSTRAINT pk_fenomeno_lunar PRIMARY KEY (cod_fenomeno),
    CONSTRAINT ck_lunar_tipo CHECK (tipo_clasificacion = 'LUNAR'),
    CONSTRAINT ck_lunar_fase CHECK (fase IN ('Nueva','Creciente','Llena','Menguante')),
    CONSTRAINT fk_lunar_fenomeno FOREIGN KEY (cod_fenomeno, tipo_clasificacion)
        REFERENCES fenomeno_astronomico (cod_fenomeno, tipo_clasificacion)
) ENGINE=InnoDB;

CREATE TABLE fenomeno_espacio_profundo (
    cod_fenomeno       INT         NOT NULL,
    tipo_clasificacion VARCHAR(20) NOT NULL DEFAULT 'ESPACIO_PROFUNDO',
    constelacion       VARCHAR(60) NOT NULL,
    CONSTRAINT pk_fenomeno_ep PRIMARY KEY (cod_fenomeno),
    CONSTRAINT ck_ep_tipo CHECK (tipo_clasificacion = 'ESPACIO_PROFUNDO'),
    CONSTRAINT fk_ep_fenomeno FOREIGN KEY (cod_fenomeno, tipo_clasificacion)
        REFERENCES fenomeno_astronomico (cod_fenomeno, tipo_clasificacion)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- REGISTRO ZONA-FENOMENO (asociativa de la relación N:M "Observa").
-- Clave surrogate: un mismo fenómeno puede observarse varias veces en la
-- misma zona en fechas distintas.
-- ---------------------------------------------------------------------
CREATE TABLE registro_observacion (
    id_registro       INT          NOT NULL AUTO_INCREMENT,
    cod_centro        INT          NOT NULL,
    n_zona            SMALLINT     NOT NULL,
    cod_fenomeno      INT          NOT NULL,
    fecha_observacion DATE         NOT NULL,
    observaciones     VARCHAR(255) NULL,
    CONSTRAINT pk_registro PRIMARY KEY (id_registro),
    CONSTRAINT fk_registro_zona FOREIGN KEY (cod_centro, n_zona)
        REFERENCES zona_observacion (cod_centro, n_zona),
    CONSTRAINT fk_registro_fenomeno FOREIGN KEY (cod_fenomeno)
        REFERENCES fenomeno_astronomico (cod_fenomeno)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- PERSONAL + especialización total y disjunta (4 subtipos)
-- ---------------------------------------------------------------------
CREATE TABLE personal (
    rut_personal    VARCHAR(12)  NOT NULL,
    primer_nombre   VARCHAR(50)  NOT NULL,
    primer_apellido VARCHAR(50)  NOT NULL,
    correo          VARCHAR(120) NULL,
    tipo_personal   VARCHAR(20)  NOT NULL,
    CONSTRAINT pk_personal PRIMARY KEY (rut_personal),
    CONSTRAINT uq_personal_correo UNIQUE (correo),
    CONSTRAINT uq_personal_tipo UNIQUE (rut_personal, tipo_personal),
    CONSTRAINT ck_personal_tipo CHECK (tipo_personal IN
        ('ADMINISTRATIVO','GUIA_CIENTIFICO','TECNICO','INVESTIGADOR'))
) ENGINE=InnoDB;

CREATE TABLE personal_telefono (            -- atributo multivaluado
    rut_personal VARCHAR(12) NOT NULL,
    telefono     VARCHAR(20) NOT NULL,
    CONSTRAINT pk_personal_telefono PRIMARY KEY (rut_personal, telefono),
    CONSTRAINT fk_telefono_personal FOREIGN KEY (rut_personal)
        REFERENCES personal (rut_personal) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE personal_administrativo (
    rut_personal  VARCHAR(12) NOT NULL,
    tipo_personal VARCHAR(20) NOT NULL DEFAULT 'ADMINISTRATIVO',
    cargo         VARCHAR(60) NOT NULL,
    CONSTRAINT pk_p_admin PRIMARY KEY (rut_personal),
    CONSTRAINT ck_p_admin_tipo CHECK (tipo_personal = 'ADMINISTRATIVO'),
    CONSTRAINT fk_p_admin FOREIGN KEY (rut_personal, tipo_personal)
        REFERENCES personal (rut_personal, tipo_personal)
) ENGINE=InnoDB;

CREATE TABLE personal_guia_cientifico (
    rut_personal  VARCHAR(12) NOT NULL,
    tipo_personal VARCHAR(20) NOT NULL DEFAULT 'GUIA_CIENTIFICO',
    area          VARCHAR(60) NOT NULL,
    CONSTRAINT pk_p_guia PRIMARY KEY (rut_personal),
    CONSTRAINT ck_p_guia_tipo CHECK (tipo_personal = 'GUIA_CIENTIFICO'),
    CONSTRAINT fk_p_guia FOREIGN KEY (rut_personal, tipo_personal)
        REFERENCES personal (rut_personal, tipo_personal)
) ENGINE=InnoDB;

CREATE TABLE personal_tecnico (
    rut_personal  VARCHAR(12) NOT NULL,
    tipo_personal VARCHAR(20) NOT NULL DEFAULT 'TECNICO',
    certificacion VARCHAR(80) NOT NULL,
    CONSTRAINT pk_p_tec PRIMARY KEY (rut_personal),
    CONSTRAINT ck_p_tec_tipo CHECK (tipo_personal = 'TECNICO'),
    CONSTRAINT fk_p_tec FOREIGN KEY (rut_personal, tipo_personal)
        REFERENCES personal (rut_personal, tipo_personal)
) ENGINE=InnoDB;

CREATE TABLE personal_investigador (
    rut_personal  VARCHAR(12) NOT NULL,
    tipo_personal VARCHAR(20) NOT NULL DEFAULT 'INVESTIGADOR',
    especialidad  VARCHAR(80) NOT NULL,
    CONSTRAINT pk_p_inv PRIMARY KEY (rut_personal),
    CONSTRAINT ck_p_inv_tipo CHECK (tipo_personal = 'INVESTIGADOR'),
    CONSTRAINT fk_p_inv FOREIGN KEY (rut_personal, tipo_personal)
        REFERENCES personal (rut_personal, tipo_personal)
) ENGINE=InnoDB;

-- Relación N:M "Trabaja" entre CENTRO y PERSONAL
CREATE TABLE trabaja_en (
    cod_centro    INT         NOT NULL,
    rut_personal  VARCHAR(12) NOT NULL,
    fecha_ingreso DATE        NOT NULL,
    CONSTRAINT pk_trabaja_en PRIMARY KEY (cod_centro, rut_personal),
    CONSTRAINT fk_trabaja_centro FOREIGN KEY (cod_centro)
        REFERENCES centro_astronomico (cod_centro),
    CONSTRAINT fk_trabaja_personal FOREIGN KEY (rut_personal)
        REFERENCES personal (rut_personal) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- CUENTAS DE USUARIO Y ROLES (rol era multivaluado: se normaliza)
-- ---------------------------------------------------------------------
CREATE TABLE rol (
    id_rol      INT         NOT NULL AUTO_INCREMENT,
    nombre_rol  VARCHAR(30) NOT NULL,
    descripcion VARCHAR(200) NOT NULL,
    CONSTRAINT pk_rol PRIMARY KEY (id_rol),
    CONSTRAINT uq_rol_nombre UNIQUE (nombre_rol)
) ENGINE=InnoDB;

CREATE TABLE cuenta_usuario (
    id_cuenta      INT          NOT NULL AUTO_INCREMENT,
    nombre_usuario VARCHAR(40)  NOT NULL,
    password_hash  VARCHAR(255) NOT NULL COMMENT 'PBKDF2-SHA256: nunca se guarda la clave en texto plano',
    activo         TINYINT(1)   NOT NULL DEFAULT 1,
    rut_personal   VARCHAR(12)  NOT NULL,
    CONSTRAINT pk_cuenta PRIMARY KEY (id_cuenta),
    CONSTRAINT uq_cuenta_usuario UNIQUE (nombre_usuario),
    CONSTRAINT uq_cuenta_personal UNIQUE (rut_personal),          -- relación 1:1
    CONSTRAINT fk_cuenta_personal FOREIGN KEY (rut_personal)
        REFERENCES personal (rut_personal) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE cuenta_rol (
    id_cuenta INT NOT NULL,
    id_rol    INT NOT NULL,
    CONSTRAINT pk_cuenta_rol PRIMARY KEY (id_cuenta, id_rol),
    CONSTRAINT fk_cr_cuenta FOREIGN KEY (id_cuenta)
        REFERENCES cuenta_usuario (id_cuenta) ON DELETE CASCADE,
    CONSTRAINT fk_cr_rol FOREIGN KEY (id_rol) REFERENCES rol (id_rol)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- VISITANTE (edad = atributo derivado: NO se almacena, se calcula con
-- TIMESTAMPDIFF desde fecha_nacimiento; regla edad >= 10 en trigger)
-- ---------------------------------------------------------------------
CREATE TABLE visitante (
    id_visitante    INT         NOT NULL AUTO_INCREMENT,
    primer_nombre   VARCHAR(50) NOT NULL,
    primer_apellido VARCHAR(50) NOT NULL,
    fecha_nacimiento DATE       NOT NULL,
    CONSTRAINT pk_visitante PRIMARY KEY (id_visitante)
) ENGINE=InnoDB;

CREATE TABLE nacionalidad_visitante (        -- atributo multivaluado
    id_visitante INT         NOT NULL,
    nacionalidad VARCHAR(40) NOT NULL,
    CONSTRAINT pk_nacionalidad PRIMARY KEY (id_visitante, nacionalidad),
    CONSTRAINT fk_nac_visitante FOREIGN KEY (id_visitante)
        REFERENCES visitante (id_visitante) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- ACTIVIDAD (se realiza en UNA zona; FK compuesta hacia la entidad débil)
-- ---------------------------------------------------------------------
CREATE TABLE actividad (
    cod_actividad   INT          NOT NULL AUTO_INCREMENT,
    nombre_actividad VARCHAR(120) NOT NULL,
    fecha           DATE         NOT NULL,
    horario         TIME         NOT NULL,
    modalidad       VARCHAR(15)  NOT NULL,
    duracion_min    INT          NOT NULL COMMENT 'minutos',
    valor           DECIMAL(10,0) NOT NULL COMMENT 'CLP por visitante',
    capacidad       INT          NOT NULL,
    cod_centro      INT          NOT NULL,
    n_zona          SMALLINT     NOT NULL,
    CONSTRAINT pk_actividad PRIMARY KEY (cod_actividad),
    CONSTRAINT fk_actividad_zona FOREIGN KEY (cod_centro, n_zona)
        REFERENCES zona_observacion (cod_centro, n_zona),
    CONSTRAINT ck_actividad_modalidad CHECK (modalidad IN ('Presencial','Virtual','Mixta')),
    CONSTRAINT ck_actividad_duracion CHECK (duracion_min > 0),
    CONSTRAINT ck_actividad_valor CHECK (valor >= 0),
    CONSTRAINT ck_actividad_capacidad CHECK (capacidad > 0)
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- RESERVA (entidad asociativa VISITANTE - ACTIVIDAD)
-- ---------------------------------------------------------------------
CREATE TABLE reserva (
    id_reserva         INT         NOT NULL AUTO_INCREMENT,
    cod_actividad      INT         NOT NULL,
    id_visitante       INT         NOT NULL,
    fecha_reserva      DATE        NOT NULL,
    estado             VARCHAR(12) NOT NULL DEFAULT 'Pendiente',
    asistencia_efectiva TINYINT(1) NOT NULL DEFAULT 0,
    observaciones      VARCHAR(255) NULL,
    CONSTRAINT pk_reserva PRIMARY KEY (id_reserva),
    CONSTRAINT uq_reserva_act_vis UNIQUE (cod_actividad, id_visitante),
    CONSTRAINT fk_reserva_actividad FOREIGN KEY (cod_actividad)
        REFERENCES actividad (cod_actividad),
    CONSTRAINT fk_reserva_visitante FOREIGN KEY (id_visitante)
        REFERENCES visitante (id_visitante),
    CONSTRAINT ck_reserva_estado CHECK (estado IN ('Pendiente','Confirmada','Cancelada')),
    CONSTRAINT ck_reserva_asistencia CHECK (asistencia_efectiva IN (0,1)),
    CONSTRAINT ck_reserva_asist_estado CHECK (asistencia_efectiva = 0 OR estado = 'Confirmada')
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- EVALUACION (entidad débil de ACTIVIDAD: PK = actividad + correlativo).
-- La FK compuesta hacia RESERVA obliga a que quien evalúa haya reservado
-- esa actividad, y UNIQUE impide más de una evaluación por visitante.
-- ---------------------------------------------------------------------
CREATE TABLE evaluacion (
    cod_actividad    INT          NOT NULL,
    n_correlativo    SMALLINT     NOT NULL,
    id_visitante     INT          NOT NULL,
    calificacion     TINYINT      NOT NULL,
    fecha_evaluacion DATE         NOT NULL,
    comentario       VARCHAR(300) NULL,
    CONSTRAINT pk_evaluacion PRIMARY KEY (cod_actividad, n_correlativo),
    CONSTRAINT uq_evaluacion_act_vis UNIQUE (cod_actividad, id_visitante),
    CONSTRAINT fk_evaluacion_actividad FOREIGN KEY (cod_actividad)
        REFERENCES actividad (cod_actividad) ON DELETE CASCADE,
    CONSTRAINT fk_evaluacion_reserva FOREIGN KEY (cod_actividad, id_visitante)
        REFERENCES reserva (cod_actividad, id_visitante),
    CONSTRAINT ck_evaluacion_correlativo CHECK (n_correlativo > 0),
    CONSTRAINT ck_evaluacion_calificacion CHECK (calificacion BETWEEN 1 AND 5)
) ENGINE=InnoDB;

SET FOREIGN_KEY_CHECKS = 1;

-- Índices adicionales para las consultas de los requerimientos
CREATE INDEX ix_actividad_fecha   ON actividad (fecha);
CREATE INDEX ix_actividad_zona    ON actividad (cod_centro, n_zona);
CREATE INDEX ix_reserva_visitante ON reserva (id_visitante);
CREATE INDEX ix_registro_zona     ON registro_observacion (cod_centro, n_zona);
CREATE INDEX ix_registro_fenomeno ON registro_observacion (cod_fenomeno);
-- =====================================================================
-- Parte 2: triggers que implementan reglas de negocio que un CHECK no
-- puede expresar (referencian otras tablas o la fecha actual).
-- =====================================================================
USE astronomia_turismo;

DELIMITER $$

-- RN: un visitante no puede tener menos de 10 años
CREATE TRIGGER trg_visitante_edad_bi BEFORE INSERT ON visitante
FOR EACH ROW
BEGIN
    IF NEW.fecha_nacimiento > DATE_SUB(CURDATE(), INTERVAL 10 YEAR) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El visitante debe tener al menos 10 anios de edad';
    END IF;
END$$

CREATE TRIGGER trg_visitante_edad_bu BEFORE UPDATE ON visitante
FOR EACH ROW
BEGIN
    IF NEW.fecha_nacimiento > DATE_SUB(CURDATE(), INTERVAL 10 YEAR) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El visitante debe tener al menos 10 anios de edad';
    END IF;
END$$

-- RN: la capacidad de una actividad no puede superar la de su zona
CREATE TRIGGER trg_actividad_capacidad_bi BEFORE INSERT ON actividad
FOR EACH ROW
BEGIN
    DECLARE v_cap INT;
    SELECT capacidad_maxima INTO v_cap FROM zona_observacion
     WHERE cod_centro = NEW.cod_centro AND n_zona = NEW.n_zona;
    IF NEW.capacidad > v_cap THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La capacidad de la actividad supera la capacidad de la zona';
    END IF;
END$$

-- RN: no se puede reservar sobre una actividad con cupos agotados, ni
-- reservar con fecha posterior a la actividad
CREATE TRIGGER trg_reserva_cupo_bi BEFORE INSERT ON reserva
FOR EACH ROW
BEGIN
    DECLARE v_cap INT;
    DECLARE v_fecha DATE;
    DECLARE v_ocupados INT;
    SELECT capacidad, fecha INTO v_cap, v_fecha
      FROM actividad WHERE cod_actividad = NEW.cod_actividad;
    IF NEW.fecha_reserva > v_fecha THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La fecha de reserva no puede ser posterior a la fecha de la actividad';
    END IF;
    IF NEW.estado <> 'Cancelada' THEN
        SELECT COUNT(*) INTO v_ocupados FROM reserva
         WHERE cod_actividad = NEW.cod_actividad AND estado <> 'Cancelada';
        IF v_ocupados >= v_cap THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'La actividad no tiene cupos disponibles';
        END IF;
    END IF;
END$$

-- RN: solo evalúa quien asistió efectivamente, y después de la actividad
CREATE TRIGGER trg_evaluacion_bi BEFORE INSERT ON evaluacion
FOR EACH ROW
BEGIN
    DECLARE v_asistio TINYINT;
    DECLARE v_fecha DATE;
    SELECT r.asistencia_efectiva, a.fecha INTO v_asistio, v_fecha
      FROM reserva r JOIN actividad a ON a.cod_actividad = r.cod_actividad
     WHERE r.cod_actividad = NEW.cod_actividad AND r.id_visitante = NEW.id_visitante;
    IF v_asistio IS NULL OR v_asistio = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Solo puede evaluar un visitante que asistio a la actividad';
    END IF;
    IF NEW.fecha_evaluacion < v_fecha THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La evaluacion no puede ser anterior a la actividad';
    END IF;
END$$

DELIMITER ;
