-- =====================================================================
-- Parte 4: 6 vistas (R2, R3, R5, R6, R7, R8)
-- "Asistente" = reserva con asistencia_efectiva = 1.
-- =====================================================================
USE astronomia_turismo;

-- R2: distribución de fenómenos CLASIFICADOS (solar/lunar/espacio profundo)
-- por centro y zona donde fueron observados.
CREATE OR REPLACE VIEW vw_r2_distribucion_fenomenos AS
SELECT c.cod_centro,
       c.nombre_centro,
       z.n_zona,
       z.nombre_zona,
       CASE WHEN s.cod_fenomeno IS NOT NULL THEN 'Solar'
            WHEN l.cod_fenomeno IS NOT NULL THEN 'Lunar'
            ELSE 'Espacio profundo' END                         AS tipo_fenomeno,
       COUNT(DISTINCT f.cod_fenomeno)                           AS fenomenos_distintos,
       COUNT(ro.id_registro)                                    AS registros_observacion,
       ROUND(100 * COUNT(DISTINCT f.cod_fenomeno) /
             SUM(COUNT(DISTINCT f.cod_fenomeno)) OVER (PARTITION BY c.cod_centro, z.n_zona), 1)
                                                                AS pct_en_la_zona
  FROM fenomeno_astronomico f
  LEFT JOIN fenomeno_solar s            ON s.cod_fenomeno = f.cod_fenomeno
  LEFT JOIN fenomeno_lunar l            ON l.cod_fenomeno = f.cod_fenomeno
  LEFT JOIN fenomeno_espacio_profundo e ON e.cod_fenomeno = f.cod_fenomeno
  JOIN registro_observacion ro          ON ro.cod_fenomeno = f.cod_fenomeno
  JOIN zona_observacion z               ON z.cod_centro = ro.cod_centro AND z.n_zona = ro.n_zona
  JOIN centro_astronomico c             ON c.cod_centro = z.cod_centro
 WHERE f.tipo_clasificacion IS NOT NULL
 GROUP BY c.cod_centro, c.nombre_centro, z.n_zona, z.nombre_zona,
          CASE WHEN s.cod_fenomeno IS NOT NULL THEN 'Solar'
               WHEN l.cod_fenomeno IS NOT NULL THEN 'Lunar'
               ELSE 'Espacio profundo' END;

-- R3: asistentes vs evaluación promedio por actividad, con centro y zona
CREATE OR REPLACE VIEW vw_r3_asistentes_vs_evaluacion AS
SELECT a.cod_actividad,
       a.nombre_actividad,
       a.fecha,
       c.nombre_centro,
       z.nombre_zona,
       SUM(r.asistencia_efectiva)           AS asistentes,
       COUNT(e.n_correlativo)               AS evaluaciones,
       ROUND(AVG(e.calificacion), 2)        AS evaluacion_promedio
  FROM actividad a
  JOIN zona_observacion z   ON z.cod_centro = a.cod_centro AND z.n_zona = a.n_zona
  JOIN centro_astronomico c ON c.cod_centro = z.cod_centro
  JOIN reserva r            ON r.cod_actividad = a.cod_actividad
  LEFT JOIN evaluacion e    ON e.cod_actividad = r.cod_actividad AND e.id_visitante = r.id_visitante
 GROUP BY a.cod_actividad, a.nombre_actividad, a.fecha, c.nombre_centro, z.nombre_zona
HAVING SUM(r.asistencia_efectiva) > 0;

-- R5: tasa de asistencia efectiva por zona (sobre reservas no canceladas)
CREATE OR REPLACE VIEW vw_r5_tasa_asistencia_zona AS
SELECT c.nombre_centro,
       z.n_zona,
       z.nombre_zona,
       COUNT(r.id_reserva)                                       AS reservas_realizadas,
       SUM(r.asistencia_efectiva)                                AS asistencias,
       ROUND(100 * SUM(r.asistencia_efectiva) / COUNT(r.id_reserva), 1) AS tasa_asistencia_pct
  FROM centro_astronomico c
  JOIN zona_observacion z ON z.cod_centro = c.cod_centro
  JOIN actividad a        ON a.cod_centro = z.cod_centro AND a.n_zona = z.n_zona
  JOIN reserva r          ON r.cod_actividad = a.cod_actividad
 WHERE r.estado <> 'Cancelada'
   AND a.fecha <= CURDATE()
 GROUP BY c.nombre_centro, z.n_zona, z.nombre_zona;

-- R6: fenómenos con más registros de observación por centro y zona
CREATE OR REPLACE VIEW vw_r6_fenomenos_mas_observados AS
SELECT c.nombre_centro,
       z.nombre_zona,
       f.nombre_fenomeno,
       COUNT(ro.id_registro)       AS total_registros,
       MIN(ro.fecha_observacion)   AS primera_observacion,
       MAX(ro.fecha_observacion)   AS ultima_observacion
  FROM registro_observacion ro
  JOIN fenomeno_astronomico f ON f.cod_fenomeno = ro.cod_fenomeno
  JOIN zona_observacion z     ON z.cod_centro = ro.cod_centro AND z.n_zona = ro.n_zona
  JOIN centro_astronomico c   ON c.cod_centro = z.cod_centro
 GROUP BY c.nombre_centro, z.nombre_zona, f.nombre_fenomeno;

-- R7: diversidad de fenómenos por centro y proporción de cada tipo
CREATE OR REPLACE VIEW vw_r7_diversidad_fenomenos_centro AS
SELECT t.nombre_centro,
       t.tipo_fenomeno,
       t.fenomenos_distintos,
       SUM(t.fenomenos_distintos) OVER (PARTITION BY t.cod_centro)  AS diversidad_total_centro,
       ROUND(100 * t.fenomenos_distintos /
             SUM(t.fenomenos_distintos) OVER (PARTITION BY t.cod_centro), 1) AS proporcion_tipo_pct
  FROM (SELECT c.cod_centro,
               c.nombre_centro,
               CASE WHEN s.cod_fenomeno IS NOT NULL THEN 'Solar'
                    WHEN l.cod_fenomeno IS NOT NULL THEN 'Lunar'
                    WHEN e.cod_fenomeno IS NOT NULL THEN 'Espacio profundo'
                    ELSE 'Sin clasificar' END                 AS tipo_fenomeno,
               COUNT(DISTINCT f.cod_fenomeno)                 AS fenomenos_distintos
          FROM centro_astronomico c
          JOIN zona_observacion z               ON z.cod_centro = c.cod_centro
          JOIN registro_observacion ro          ON ro.cod_centro = z.cod_centro AND ro.n_zona = z.n_zona
          JOIN fenomeno_astronomico f           ON f.cod_fenomeno = ro.cod_fenomeno
          LEFT JOIN fenomeno_solar s            ON s.cod_fenomeno = f.cod_fenomeno
          LEFT JOIN fenomeno_lunar l            ON l.cod_fenomeno = f.cod_fenomeno
          LEFT JOIN fenomeno_espacio_profundo e ON e.cod_fenomeno = f.cod_fenomeno
         GROUP BY c.cod_centro, c.nombre_centro,
                  CASE WHEN s.cod_fenomeno IS NOT NULL THEN 'Solar'
                       WHEN l.cod_fenomeno IS NOT NULL THEN 'Lunar'
                       WHEN e.cod_fenomeno IS NOT NULL THEN 'Espacio profundo'
                       ELSE 'Sin clasificar' END) t;

-- R8: visitantes con mayor participación y valor total de sus reservas
CREATE OR REPLACE VIEW vw_r8_visitantes_participacion AS
SELECT v.id_visitante,
       CONCAT(v.primer_nombre, ' ', v.primer_apellido) AS visitante,
       COUNT(r.id_reserva)                             AS reservas_activas,
       SUM(r.asistencia_efectiva)                      AS asistencias,
       COUNT(DISTINCT a.cod_centro)                    AS centros_distintos,
       SUM(a.valor)                                    AS valor_total_reservado
  FROM visitante v
  JOIN reserva r           ON r.id_visitante = v.id_visitante
  JOIN actividad a         ON a.cod_actividad = r.cod_actividad
  JOIN zona_observacion z  ON z.cod_centro = a.cod_centro AND z.n_zona = a.n_zona
 WHERE r.estado <> 'Cancelada'
 GROUP BY v.id_visitante, v.primer_nombre, v.primer_apellido
HAVING COUNT(r.id_reserva) >= 8;
-- =====================================================================
-- Parte 5: 6 procedimientos almacenados (R1, R4, R9, R10, R11, R12)
-- =====================================================================
USE astronomia_turismo;

DELIMITER $$

-- R1: zonas con mayor cantidad de visitantes (asistentes) en un período
CREATE PROCEDURE sp_r1_zonas_mas_visitadas(IN p_inicio DATE, IN p_fin DATE)
BEGIN
    SELECT c.nombre_centro,
           z.n_zona,
           z.nombre_zona,
           COUNT(DISTINCT a.cod_actividad)  AS actividades,
           COUNT(DISTINCT r.id_visitante)   AS visitantes_distintos,
           COUNT(r.id_reserva)              AS asistencias_totales
      FROM centro_astronomico c
      JOIN zona_observacion z ON z.cod_centro = c.cod_centro
      JOIN actividad a        ON a.cod_centro = z.cod_centro AND a.n_zona = z.n_zona
      JOIN reserva r          ON r.cod_actividad = a.cod_actividad
     WHERE r.asistencia_efectiva = 1
       AND a.fecha BETWEEN p_inicio AND p_fin
     GROUP BY c.nombre_centro, z.n_zona, z.nombre_zona
     ORDER BY asistencias_totales DESC, visitantes_distintos DESC;
END$$

-- R4: centros que concentran más actividades y visitantes en un período
CREATE PROCEDURE sp_r4_centros_concentracion(IN p_inicio DATE, IN p_fin DATE)
BEGIN
    SELECT c.cod_centro,
           c.nombre_centro,
           COUNT(DISTINCT a.cod_actividad)                  AS actividades,
           COUNT(DISTINCT z.n_zona)                         AS zonas_utilizadas,
           COUNT(DISTINCT CASE WHEN r.asistencia_efectiva = 1 THEN r.id_visitante END)
                                                            AS visitantes_distintos,
           SUM(r.asistencia_efectiva)                       AS asistencias_totales
      FROM centro_astronomico c
      JOIN zona_observacion z ON z.cod_centro = c.cod_centro
      JOIN actividad a        ON a.cod_centro = z.cod_centro AND a.n_zona = z.n_zona
      LEFT JOIN reserva r     ON r.cod_actividad = a.cod_actividad
     WHERE a.fecha BETWEEN p_inicio AND p_fin
     GROUP BY c.cod_centro, c.nombre_centro
     ORDER BY actividades DESC, asistencias_totales DESC;
END$$

-- R9: actividades cuyos asistentes superan el promedio de actividades del
-- mismo centro en el período (subconsultas correlacionadas).
-- p_cod_centro NULL = todos los centros.
CREATE PROCEDURE sp_r9_actividades_sobre_promedio(IN p_cod_centro INT, IN p_inicio DATE, IN p_fin DATE)
BEGIN
    SELECT c.nombre_centro,
           z.nombre_zona,
           a.cod_actividad,
           a.nombre_actividad,
           a.fecha,
           SUM(r.asistencia_efectiva) AS asistentes,
           ROUND((SELECT SUM(r2.asistencia_efectiva)
                    FROM reserva r2
                    JOIN actividad a2 ON a2.cod_actividad = r2.cod_actividad
                   WHERE a2.cod_centro = a.cod_centro
                     AND a2.fecha BETWEEN p_inicio AND p_fin)
                 / (SELECT COUNT(*) FROM actividad a3
                     WHERE a3.cod_centro = a.cod_centro
                       AND a3.fecha BETWEEN p_inicio AND p_fin), 2) AS promedio_centro
      FROM actividad a
      JOIN zona_observacion z   ON z.cod_centro = a.cod_centro AND z.n_zona = a.n_zona
      JOIN centro_astronomico c ON c.cod_centro = z.cod_centro
      JOIN reserva r            ON r.cod_actividad = a.cod_actividad
     WHERE a.fecha BETWEEN p_inicio AND p_fin
       AND (p_cod_centro IS NULL OR a.cod_centro = p_cod_centro)
     GROUP BY c.nombre_centro, z.nombre_zona, a.cod_actividad, a.nombre_actividad, a.fecha, a.cod_centro
    HAVING SUM(r.asistencia_efectiva) >
           (SELECT SUM(r2.asistencia_efectiva)
              FROM reserva r2
              JOIN actividad a2 ON a2.cod_actividad = r2.cod_actividad
             WHERE a2.cod_centro = a.cod_centro
               AND a2.fecha BETWEEN p_inicio AND p_fin)
           / (SELECT COUNT(*) FROM actividad a3
               WHERE a3.cod_centro = a.cod_centro
                 AND a3.fecha BETWEEN p_inicio AND p_fin)
     ORDER BY c.nombre_centro, asistentes DESC;
END$$

-- R10: zonas más oscuras que el promedio de su centro y sus actividades
CREATE PROCEDURE sp_r10_zonas_oscuras(IN p_cod_centro INT)
BEGIN
    SELECT c.nombre_centro,
           z.n_zona,
           z.nombre_zona,
           z.nivel_oscuridad,
           ROUND((SELECT AVG(z2.nivel_oscuridad) FROM zona_observacion z2
                   WHERE z2.cod_centro = z.cod_centro), 2) AS oscuridad_promedio_centro,
           a.cod_actividad,
           a.nombre_actividad,
           a.fecha
      FROM centro_astronomico c
      JOIN zona_observacion z ON z.cod_centro = c.cod_centro
      LEFT JOIN actividad a   ON a.cod_centro = z.cod_centro AND a.n_zona = z.n_zona
     WHERE c.cod_centro = p_cod_centro
       AND z.nivel_oscuridad > (SELECT AVG(z2.nivel_oscuridad) FROM zona_observacion z2
                                 WHERE z2.cod_centro = z.cod_centro)
     ORDER BY z.nivel_oscuridad DESC, a.fecha;
END$$

-- R11: visitantes con más actividades que el promedio y evaluación
-- promedio superior a la general, en un rango de fechas
CREATE PROCEDURE sp_r11_visitantes_destacados(IN p_inicio DATE, IN p_fin DATE)
BEGIN
    SELECT v.id_visitante,
           CONCAT(v.primer_nombre, ' ', v.primer_apellido) AS visitante,
           COUNT(r.id_reserva)                             AS actividades_asistidas,
           ROUND(AVG(e.calificacion), 2)                   AS evaluacion_promedio
      FROM visitante v
      JOIN reserva r         ON r.id_visitante = v.id_visitante
      JOIN actividad a       ON a.cod_actividad = r.cod_actividad
      LEFT JOIN evaluacion e ON e.cod_actividad = r.cod_actividad AND e.id_visitante = r.id_visitante
     WHERE r.asistencia_efectiva = 1
       AND a.fecha BETWEEN p_inicio AND p_fin
     GROUP BY v.id_visitante, v.primer_nombre, v.primer_apellido
    HAVING COUNT(r.id_reserva) >
           (SELECT AVG(t.n) FROM (SELECT COUNT(*) AS n
                                    FROM reserva r2
                                    JOIN actividad a2 ON a2.cod_actividad = r2.cod_actividad
                                   WHERE r2.asistencia_efectiva = 1
                                     AND a2.fecha BETWEEN p_inicio AND p_fin
                                   GROUP BY r2.id_visitante) t)
       AND AVG(e.calificacion) >
           (SELECT AVG(e3.calificacion)
              FROM evaluacion e3
              JOIN actividad a3 ON a3.cod_actividad = e3.cod_actividad
             WHERE a3.fecha BETWEEN p_inicio AND p_fin)
     ORDER BY actividades_asistidas DESC, evaluacion_promedio DESC;
END$$

-- R12: centros con promedio de asistentes por actividad superior al
-- promedio general de los centros, en un período
CREATE PROCEDURE sp_r12_centros_sobre_promedio(IN p_inicio DATE, IN p_fin DATE)
BEGIN
    WITH asist_actividad AS (
        SELECT a.cod_centro, a.cod_actividad, COALESCE(SUM(r.asistencia_efectiva), 0) AS asistentes
          FROM actividad a
          JOIN zona_observacion z ON z.cod_centro = a.cod_centro AND z.n_zona = a.n_zona
          LEFT JOIN reserva r     ON r.cod_actividad = a.cod_actividad
         WHERE a.fecha BETWEEN p_inicio AND p_fin
         GROUP BY a.cod_centro, a.cod_actividad
    ),
    prom_centro AS (
        SELECT cod_centro, COUNT(*) AS actividades, AVG(asistentes) AS promedio
          FROM asist_actividad
         GROUP BY cod_centro
    )
    SELECT c.nombre_centro,
           pc.actividades,
           ROUND(pc.promedio, 2) AS promedio_asistentes,
           ROUND((SELECT AVG(promedio) FROM prom_centro), 2) AS promedio_general_centros
      FROM prom_centro pc
      JOIN centro_astronomico c ON c.cod_centro = pc.cod_centro
     WHERE pc.promedio > (SELECT AVG(promedio) FROM prom_centro)
     ORDER BY pc.promedio DESC;
END$$

DELIMITER ;
